C.aJp=new B.I("1. Veri Sorumlusu: Veri sorumlusu uygulamay\u0131 kullanan psikolog/klinik i\u015fletmesidir.\n\n2. \u0130\u015flenen Veriler: Dan\u0131\u015fan ad-soyad, ileti\u015fim bilgileri, de\u011ferlendirme cevaplar\u0131, seans notlar\u0131 ve tedavi plan\u0131 bilgileri.\n\n3. \u0130\u015fleme Amac\u0131: Klinik s\xfcre\xe7 y\xf6netimi, de\u011ferlendirme takibi ve tedavi planlamas\u0131.\n\n4. Saklama: Klinik kay\u0131tlar ba\u011fl\u0131 sunucu hesab\u0131nda ve \xe7al\u0131\u015fma cihaz\u0131ndaki uygulama \xf6nbelle\u011finde saklanabilir. Yetkisiz eri\u015fimi \xf6nlemek i\xe7in hesap bilgilerinizi payla\u015fmay\u0131n.\n\n5. G\xfcvenlik: \u015eifreler tek y\xf6nl\xfc \xf6zetleme (SHA-256) ile saklan\u0131r. Cihaz d\xfczeyinde ek koruma i\xe7in i\u015fletim sisteminizin disk \u015fifrelemesini etkinle\u015ftirmeniz \xf6nerilir.\n\n6. Haklar\u0131n\u0131z: KVKK kapsam\u0131nda verilere eri\u015fim, d\xfczeltme ve silme haklar\u0131n\u0131z\u0131 bu uygulaman\u0131n Ayarlar b\xf6l\xfcm\xfcnden kullanabilirsiniz.\n\nUyar\u0131: Bu uygulama t\u0131bbi tan\u0131 veya tedavi arac\u0131 de\u011fildir; bir sa\u011fl\u0131k profesyonelinin mesleki kararlar\u0131n\u0131 destekleyen bir kay\u0131t arac\u0131d\u0131r.",null,C.aDJ,null,null,null,null,null,null,null,null)
